parameters.jsCode:
const item = $input.first().json;
const content = item?.choices?.[0]?.message?.content ?? '{}';
let data;
try { data = JSON.parse(content); } catch (e) { data = { should_reply: false, reply_draft: '' }; }
const trig = $('When Email Received').first().json;
function asText(v){
  if(v == null) return '';
  if(typeof v === 'string') return v;
  if(typeof v === 'object'){
    if(typeof v.text === 'string') return v.text;
    if(Array.isArray(v.value) && v.value[0]) return v.value[0].address || v.value[0].name || '';
    if(typeof v.address === 'string') return v.address;
    return '';
  }
  return String(v);
}
return [{ json: {
  should_reply: data.should_reply === true,
  reply_draft: data.reply_draft ?? '',
  subject: asText(trig.subject ?? trig.Subject),
} }];
